1 void merge(int arr[], int left, int mid, int right) {
2     int n1 = mid - left + 1;
3     int n2 = right - mid;
4     vector<int> L(n1), R(n2);
5 
6     for (int i = 0; i < n1; i++) L[i] = arr[left + i];
7     for (int j = 0; j < n2; j++) R[j] = arr[mid + 1 + j];
8     int i = 0, j = 0, k = left;
9     while (i < n1 && j < n2) {
10        if (L[i] <= R[j]) arr[k++] = L[i++];
11        else arr[k++] = R[j++];
12    }
